insert into public.books (id, slug, title, subtitle, authors, description, cover_url, isbn13, isbn10, ol_work_id, ol_edition_id, published_year, publisher, page_count, language, genres, moods, created_at) values
  ('9cb6880e-10ae-4805-afaa-d721fc295c3b', 'piranesi', 'Piranesi', null, array['Susanna Clarke']::text[], 'A man lives in a House of endless marble halls, tidal staircases and statues, keeping meticulous journals of its weather and its birds. A quiet, luminous puzzle about wonder, memory and what it costs to be found.', 'https://covers.openlibrary.org/b/isbn/9781635575637-L.jpg?default=false', '9781635575637', null, null, null, 2020, 'Bloomsbury', 272, 'English', array['fantasy','literary fiction']::text[], array['dreamy','hopeful','rainy-day']::text[], '2025-06-22T12:30:48.980Z'),
  ('cae096d0-4811-466c-b032-eb01a21da296', 'secret-history', 'The Secret History', null, array['Donna Tartt']::text[], 'A scholarship student falls in with an insular circle of Classics students at a Vermont college, and learns exactly how far beauty and Greek can carry a group of friends toward murder. The urtext of dark academia.', 'https://covers.openlibrary.org/b/isbn/9781400031702-L.jpg?default=false', '9781400031702', null, null, null, 1992, 'Vintage', 559, 'English', array['dark academia','literary fiction','mystery']::text[], array['unsettling','melancholic','tense']::text[], '2025-06-22T13:37:24.980Z'),
  ('d3e1c206-2d2e-4228-a149-8d58f8903543', 'normal-people', 'Normal People', null, array['Sally Rooney']::text[], 'Connell and Marianne orbit each other from a small town in the west of Ireland to Trinity College Dublin, misunderstanding and rescuing one another in equal measure.', 'https://covers.openlibrary.org/b/isbn/9781984822185-L.jpg?default=false', '9781984822185', null, null, null, 2018, 'Hogarth', 273, 'English', array['contemporary','literary fiction','romance']::text[], array['heartbreaking','romantic','reflective']::text[], '2025-06-22T10:27:12.980Z'),
  ('74dfcea9-de64-4637-ba87-d7514f7d8975', 'a-little-life', 'A Little Life', null, array['Hanya Yanagihara']::text[], 'Four college friends build lives in New York over decades, while one of them, Jude, carries a past he cannot speak about. Enormous, devastating, and impossible to read casually.', 'https://covers.openlibrary.org/b/isbn/9780804172707-L.jpg?default=false', '9780804172707', null, null, null, 2015, 'Anchor', 832, 'English', array['literary fiction','contemporary']::text[], array['heartbreaking','melancholic']::text[], '2025-06-22T13:42:12.980Z'),
  ('d0301399-bcab-4584-97f4-0511d13959c0', 'never-let-me-go', 'Never Let Me Go', null, array['Kazuo Ishiguro']::text[], 'Kathy remembers her childhood at Hailsham, an English boarding school where the students were told they were special. A soft-spoken novel whose quietness is its horror.', 'https://covers.openlibrary.org/b/isbn/9781400078776-L.jpg?default=false', '9781400078776', null, null, null, 2005, 'Vintage', 288, 'English', array['literary fiction','sci-fi']::text[], array['melancholic','heartbreaking','reflective']::text[], '2025-06-22T09:18:30.980Z'),
  ('f6d6ee67-a698-435c-bf45-c86e7bfe29ac', 'song-of-achilles', 'The Song of Achilles', null, array['Madeline Miller']::text[], 'The Iliad retold by Patroclus, exiled prince and Achilles'' companion, from boyhood in Phthia to the walls of Troy. You know how it ends. It ruins you anyway.', 'https://covers.openlibrary.org/b/isbn/9780062060624-L.jpg?default=false', '9780062060624', null, null, null, 2011, 'Ecco', 378, 'English', array['mythology','historical fiction','romance']::text[], array['romantic','heartbreaking']::text[], '2025-06-22T10:03:12.980Z'),
  ('e66bf754-65ea-4692-9c11-8dc2f964f081', 'circe', 'Circe', null, array['Madeline Miller']::text[], 'The witch of Aiaia, banished daughter of Helios, tells her own story: gods and monsters, Odysseus and Daedalus, and the long work of becoming oneself.', 'https://covers.openlibrary.org/b/isbn/9780316556347-L.jpg?default=false', '9780316556347', null, null, null, 2018, 'Little, Brown', 393, 'English', array['mythology','fantasy']::text[], array['reflective','hopeful','adventurous']::text[], '2025-06-22T10:31:06.980Z'),
  ('dfecb946-eb27-4366-9f7a-dd5d1548dba5', 'klara-and-the-sun', 'Klara and the Sun', null, array['Kazuo Ishiguro']::text[], 'An Artificial Friend watches the world from a shop window, then from inside a family''s fragile home, trying to understand love by watching the Sun.', 'https://covers.openlibrary.org/b/isbn/9780593318171-L.jpg?default=false', '9780593318171', null, null, null, 2021, 'Knopf', 303, 'English', array['literary fiction','sci-fi']::text[], array['melancholic','hopeful','reflective']::text[], '2025-06-22T11:28:42.980Z'),
  ('36fb535b-52c5-419d-903b-a6c87f6f50e5', 'tomorrow-x3', 'Tomorrow, and Tomorrow, and Tomorrow', null, array['Gabrielle Zevin']::text[], 'Two friends make video games together across thirty years — partners, rivals, never quite lovers. A novel about creative collaboration as a form of intimacy.', 'https://covers.openlibrary.org/b/isbn/9780593321201-L.jpg?default=false', '9780593321201', null, null, null, 2022, 'Knopf', 416, 'English', array['contemporary','literary fiction']::text[], array['reflective','heartbreaking','hopeful']::text[], '2025-06-22T10:36:12.980Z'),
  ('86f39409-f9ed-414f-9057-ed091d8d380d', 'bell-jar', 'The Bell Jar', null, array['Sylvia Plath']::text[], 'Esther Greenwood wins a summer internship at a New York magazine and feels the glass close around her. Sharp, funny and frightening about the expectations placed on young women.', 'https://covers.openlibrary.org/b/isbn/9780060837020-L.jpg?default=false', '9780060837020', null, null, null, 1963, 'Harper Perennial', 294, 'English', array['classics','literary fiction']::text[], array['melancholic','reflective']::text[], '2025-06-22T14:07:24.980Z'),
  ('96c82f65-6dda-4479-ac5b-e253e90c3d25', 'pachinko', 'Pachinko', null, array['Min Jin Lee']::text[], 'Four generations of a Korean family make a life in Japan across the twentieth century. Patient, sweeping and full of small mercies.', 'https://covers.openlibrary.org/b/isbn/9781455563920-L.jpg?default=false', '9781455563920', null, null, null, 2017, 'Grand Central', 496, 'English', array['historical fiction','literary fiction']::text[], array['heartbreaking','hopeful']::text[], '2025-06-22T12:15:48.980Z'),
  ('6dea3f39-b22e-4346-81e9-3dfc3df54cd4', 'night-circus', 'The Night Circus', null, array['Erin Morgenstern']::text[], 'A black-and-white circus open only at night is the stage for a duel between two young magicians who were never meant to fall in love.', 'https://covers.openlibrary.org/b/isbn/9780307744432-L.jpg?default=false', '9780307744432', null, null, null, 2011, 'Anchor', 400, 'English', array['fantasy','romance']::text[], array['dreamy','romantic','cosy']::text[], '2025-06-22T13:30:30.980Z'),
  ('4c89d5a0-8136-45e5-b779-ecf85cab6264', 'norwegian-wood', 'Norwegian Wood', null, array['Haruki Murakami']::text[], 'A Beatles song carries Toru back to Tokyo in the late sixties, to Naoko and to Midori, grief and first love. Murakami at his most realist and most tender.', 'https://covers.openlibrary.org/b/isbn/9780375704024-L.jpg?default=false', '9780375704024', null, null, null, 1987, 'Vintage', 296, 'English', array['literary fiction','romance']::text[], array['melancholic','romantic','rainy-day']::text[], '2025-06-22T10:30:30.980Z'),
  ('127e4dec-d97b-4f65-8ad7-8c6d02eedb64', 'mrs-dalloway', 'Mrs Dalloway', null, array['Virginia Woolf']::text[], 'A single June day in London: Clarissa Dalloway prepares for a party while a shell-shocked veteran walks the same streets. Consciousness rendered like light through water.', 'https://covers.openlibrary.org/b/isbn/9780156628709-L.jpg?default=false', '9780156628709', null, null, null, 1925, 'Harcourt', 194, 'English', array['classics','literary fiction']::text[], array['reflective','dreamy']::text[], '2025-06-22T13:05:54.980Z'),
  ('d0d3f8dd-b7f0-40ac-91b8-a6850c6ff56b', 'giovannis-room', 'Giovanni''s Room', null, array['James Baldwin']::text[], 'In Paris, an American man waiting for his fiancée falls for an Italian bartender and cannot forgive himself for it. Short, exquisite and unbearably honest.', 'https://covers.openlibrary.org/b/isbn/9780345806567-L.jpg?default=false', '9780345806567', null, null, null, 1956, 'Vintage', 169, 'English', array['classics','literary fiction','romance']::text[], array['heartbreaking','melancholic']::text[], '2025-06-22T10:58:42.980Z'),
  ('d5c46ad2-f9c8-4fe7-aff0-93ae5a6a072a', 'beloved', 'Beloved', null, array['Toni Morrison']::text[], 'Sethe escaped slavery, but in a house on Bluestone Road in Ohio the past has a body and a name. A ghost story that is also a reckoning.', 'https://covers.openlibrary.org/b/isbn/9781400033416-L.jpg?default=false', '9781400033416', null, null, null, 1987, 'Vintage', 324, 'English', array['classics','historical fiction']::text[], array['unsettling','heartbreaking']::text[], '2025-06-22T11:32:36.980Z'),
  ('ef46c227-875c-43e8-aeb0-47532151dacf', 'remains-of-the-day', 'The Remains of the Day', null, array['Kazuo Ishiguro']::text[], 'An English butler takes a motoring trip across the West Country and slowly, politely, avoids looking at the life he did not live.', 'https://covers.openlibrary.org/b/isbn/9780679731726-L.jpg?default=false', '9780679731726', null, null, null, 1989, 'Vintage', 245, 'English', array['literary fiction','classics']::text[], array['melancholic','reflective']::text[], '2025-06-22T12:37:06.980Z'),
  ('f613a2e3-69c0-4bd8-a4ec-fb5a8cdea4e4', 'jane-eyre', 'Jane Eyre', null, array['Charlotte Brontë']::text[], 'An orphaned governess with a fierce conscience arrives at Thornfield Hall, where the master is brooding and the attic is not empty.', 'https://covers.openlibrary.org/b/isbn/9780141441146-L.jpg?default=false', '9780141441146', null, null, null, 1847, 'Penguin Classics', 532, 'English', array['classics','romance','gothic']::text[], array['romantic','unsettling','rainy-day']::text[], '2025-06-22T14:01:42.980Z'),
  ('433234b6-05d9-4940-9154-393190c78cad', 'pride-and-prejudice', 'Pride and Prejudice', null, array['Jane Austen']::text[], 'Elizabeth Bennet and Mr Darcy misjudge one another magnificently. Still the funniest, sharpest romance in the canon.', 'https://covers.openlibrary.org/b/isbn/9780141439518-L.jpg?default=false', '9780141439518', null, null, null, 1813, 'Penguin Classics', 480, 'English', array['classics','romance']::text[], array['funny','romantic','cosy']::text[], '2025-06-22T11:18:30.980Z'),
  ('d6eb9eca-3445-419f-ac5a-fec9e65d350c', 'frankenstein', 'Frankenstein', null, array['Mary Shelley']::text[], 'A young scientist makes a living creature and abandons it. Written by a nineteen-year-old, it invented science fiction and has not stopped asking who the monster is.', 'https://covers.openlibrary.org/b/isbn/9780141439471-L.jpg?default=false', '9780141439471', null, null, null, 1818, 'Penguin Classics', 280, 'English', array['classics','horror','gothic','sci-fi']::text[], array['unsettling','melancholic']::text[], '2025-06-22T11:01:06.980Z'),
  ('e846c585-f27d-40b9-9fa8-12a8c099b027', 'rest-and-relaxation', 'My Year of Rest and Relaxation', null, array['Ottessa Moshfegh']::text[], 'A young woman in 2000s Manhattan decides to sleep for a year with the help of a spectacularly irresponsible psychiatrist. Bleak, bratty and very funny.', 'https://covers.openlibrary.org/b/isbn/9780525522133-L.jpg?default=false', '9780525522133', null, null, null, 2018, 'Penguin Press', 289, 'English', array['contemporary','literary fiction']::text[], array['funny','unsettling']::text[], '2025-06-22T14:04:42.980Z'),
  ('15fe3e2d-6294-4f51-8485-224685673ec8', 'conversations-with-friends', 'Conversations with Friends', null, array['Sally Rooney']::text[], 'Frances, a student poet in Dublin, and her ex Bobbi are drawn into the lives of an older married couple. Clever people being careless with each other.', 'https://covers.openlibrary.org/b/isbn/9780451499073-L.jpg?default=false', '9780451499073', null, null, null, 2017, 'Hogarth', 321, 'English', array['contemporary','literary fiction']::text[], array['reflective','romantic']::text[], '2025-06-22T11:50:00.980Z'),
  ('14576130-d4e9-4b8c-9963-096e0d8ab9e1', 'dorian-gray', 'The Picture of Dorian Gray', null, array['Oscar Wilde']::text[], 'A beautiful young man wishes his portrait would age instead of him, and gets his wish. Epigrams and decadence over a rotting core.', 'https://covers.openlibrary.org/b/isbn/9780141439570-L.jpg?default=false', '9780141439570', null, null, null, 1890, 'Penguin Classics', 254, 'English', array['classics','gothic']::text[], array['unsettling','funny']::text[], '2025-06-22T13:47:36.980Z'),
  ('1baa8c28-6fa6-477d-a408-8be7d491e73c', 'station-eleven', 'Station Eleven', null, array['Emily St. John Mandel']::text[], 'Twenty years after a pandemic ends the world as we know it, a travelling troupe performs Shakespeare along the shores of Lake Michigan. A tender post-apocalypse.', 'https://covers.openlibrary.org/b/isbn/9780804172448-L.jpg?default=false', '9780804172448', null, null, null, 2014, 'Vintage', 333, 'English', array['sci-fi','literary fiction']::text[], array['hopeful','melancholic','reflective']::text[], '2025-06-22T09:26:54.980Z'),
  ('50ba1b5f-cc09-4dba-af91-d844b236c3e9', 'left-hand-of-darkness', 'The Left Hand of Darkness', null, array['Ursula K. Le Guin']::text[], 'An envoy is sent to the ice world of Gethen, whose people have no fixed sex. Politics, friendship and one of the great journeys across a glacier.', 'https://covers.openlibrary.org/b/isbn/9780441478125-L.jpg?default=false', '9780441478125', null, null, null, 1969, 'Ace', 304, 'English', array['sci-fi','classics']::text[], array['reflective','adventurous']::text[], '2025-06-22T14:08:36.980Z'),
  ('a5d2cc7c-ad31-436d-9c7e-f0ae2eb299cc', 'babel', 'Babel', 'Or the Necessity of Violence', array['R. F. Kuang']::text[], 'In an alternate 1830s Oxford, translation powers the British Empire through enchanted silver. A dark-academia fantasy about language, complicity and revolution.', 'https://covers.openlibrary.org/b/isbn/9780063021426-L.jpg?default=false', '9780063021426', null, null, null, 2022, 'Harper Voyager', 545, 'English', array['fantasy','dark academia','historical fiction']::text[], array['tense','heartbreaking']::text[], '2025-06-22T12:56:54.980Z'),
  ('8a083731-5d62-4ade-b584-42be651378f1', 'yellowface', 'Yellowface', null, array['R. F. Kuang']::text[], 'When her more successful friend dies, a struggling author steals her unfinished manuscript and publishes it as her own. A gleefully uncomfortable satire of publishing.', 'https://covers.openlibrary.org/b/isbn/9780063250833-L.jpg?default=false', '9780063250833', null, null, null, 2023, 'William Morrow', 336, 'English', array['contemporary','mystery']::text[], array['funny','tense']::text[], '2025-06-22T10:17:00.980Z'),
  ('1705590c-e6f1-41a7-b14e-20d761ef300a', 'evelyn-hugo', 'The Seven Husbands of Evelyn Hugo', null, array['Taylor Jenkins Reid']::text[], 'A reclusive Hollywood icon finally tells her life story to an unknown journalist — seven marriages, and the one love she hid from all of them.', 'https://covers.openlibrary.org/b/isbn/9781501161933-L.jpg?default=false', '9781501161933', null, null, null, 2017, 'Atria', 389, 'English', array['historical fiction','romance','contemporary']::text[], array['romantic','heartbreaking']::text[], '2025-06-22T09:15:12.980Z'),
  ('974a173a-9cde-4d5b-a768-7f3965156a14', 'crying-in-h-mart', 'Crying in H Mart', null, array['Michelle Zauner']::text[], 'The Japanese Breakfast musician writes about her Korean mother''s illness and death, and about cooking her way back to her through food.', 'https://covers.openlibrary.org/b/isbn/9780525657743-L.jpg?default=false', '9780525657743', null, null, null, 2021, 'Knopf', 239, 'English', array['memoir']::text[], array['heartbreaking','hopeful']::text[], '2025-06-22T10:34:42.980Z'),
  ('45f06cf9-4d8d-482a-b0d7-ba7d47695289', 'bluets', 'Bluets', null, array['Maggie Nelson']::text[], 'Two hundred and forty numbered propositions about the colour blue, heartbreak and a friend''s paralysis. Philosophy that reads like a diary.', 'https://covers.openlibrary.org/b/isbn/9781933517407-L.jpg?default=false', '9781933517407', null, null, null, 2009, 'Wave Books', 95, 'English', array['poetry','essays']::text[], array['melancholic','reflective','rainy-day']::text[], '2025-06-22T11:05:00.980Z'),
  ('1abf9a57-8de1-4a41-9977-c473ddd36c7f', 'briefly-gorgeous', 'On Earth We''re Briefly Gorgeous', null, array['Ocean Vuong']::text[], 'A letter from a son to his mother who cannot read it: Vietnam, Hartford, tobacco fields, first love. A poet''s first novel, with every sentence weighed.', 'https://covers.openlibrary.org/b/isbn/9780525562047-L.jpg?default=false', '9780525562047', null, null, null, 2019, 'Penguin Press', 246, 'English', array['literary fiction','poetry']::text[], array['heartbreaking','dreamy']::text[], '2025-06-22T13:06:48.980Z'),
  ('f7a44638-1088-4762-aedd-21386f98e9df', 'convenience-store-woman', 'Convenience Store Woman', null, array['Sayaka Murata']::text[], 'Keiko has worked at the same Tokyo convenience store for eighteen years and is perfectly content. Everyone else is horrified. Small, strange and delightful.', 'https://covers.openlibrary.org/b/isbn/9780802128256-L.jpg?default=false', '9780802128256', null, null, null, 2018, 'Grove Press', 163, 'English', array['contemporary','literary fiction']::text[], array['funny','unsettling']::text[], '2025-06-22T12:43:42.980Z'),
  ('d16151ce-3f9d-4ef3-bdb1-7caee92f1231', 'hill-house', 'The Haunting of Hill House', null, array['Shirley Jackson']::text[], 'Four people spend a summer in a house that was born bad. The finest haunted-house novel ever written, and the loneliest.', 'https://covers.openlibrary.org/b/isbn/9780143039983-L.jpg?default=false', '9780143039983', null, null, null, 1959, 'Penguin Classics', 182, 'English', array['horror','classics','gothic']::text[], array['unsettling','tense']::text[], '2025-06-22T12:30:30.980Z'),
  ('ec465430-272e-445d-ae14-e0ccb0a4dc5c', 'rebecca', 'Rebecca', null, array['Daphne du Maurier']::text[], 'A shy young bride arrives at Manderley and finds her husband''s dead first wife still in every room.', 'https://covers.openlibrary.org/b/isbn/9780380730407-L.jpg?default=false', '9780380730407', null, null, null, 1938, 'William Morrow', 410, 'English', array['classics','gothic','mystery']::text[], array['unsettling','romantic','rainy-day']::text[], '2025-06-22T11:38:00.980Z'),
  ('e6bd3ded-838c-4711-89e0-be78f7736474', 'wuthering-heights', 'Wuthering Heights', null, array['Emily Brontë']::text[], 'On the Yorkshire moors, Catherine and Heathcliff''s love curdles into a vengeance that poisons two generations. Wild weather, wilder people.', 'https://covers.openlibrary.org/b/isbn/9780141439556-L.jpg?default=false', '9780141439556', null, null, null, 1847, 'Penguin Classics', 416, 'English', array['classics','gothic','romance']::text[], array['unsettling','heartbreaking','rainy-day']::text[], '2025-06-22T13:11:18.980Z'),
  ('319cd7bf-5890-48e7-80fc-d4ecf9f47f59', 'dune', 'Dune', null, array['Frank Herbert']::text[], 'A ducal heir is thrown onto the desert planet Arrakis, sole source of the universe''s most precious substance. Ecology, empire and prophecy in the sand.', 'https://covers.openlibrary.org/b/isbn/9780441172719-L.jpg?default=false', '9780441172719', null, null, null, 1965, 'Ace', 617, 'English', array['sci-fi','classics']::text[], array['adventurous','tense']::text[], '2025-06-22T09:56:54.980Z'),
  ('150377a6-e120-4d92-b9dd-0965b4543aae', 'name-of-the-wind', 'The Name of the Wind', null, array['Patrick Rothfuss']::text[], 'An innkeeper with a legendary past tells the story of how he became Kvothe: orphan, musician, university student and seeker of a secret name.', 'https://covers.openlibrary.org/b/isbn/9780756404741-L.jpg?default=false', '9780756404741', null, null, null, 2007, 'DAW', 662, 'English', array['fantasy']::text[], array['adventurous','cosy']::text[], '2025-06-22T12:37:42.980Z'),
  ('955cae93-d2f5-436b-b898-3d1eea828957', 'kafka-on-the-shore', 'Kafka on the Shore', null, array['Haruki Murakami']::text[], 'A fifteen-year-old runaway and an old man who talks to cats are pulled toward the same small library in Takamatsu. Fish fall from the sky.', 'https://covers.openlibrary.org/b/isbn/9781400079278-L.jpg?default=false', '9781400079278', null, null, null, 2002, 'Vintage', 467, 'English', array['literary fiction','fantasy']::text[], array['dreamy','unsettling']::text[], '2025-06-22T11:50:54.980Z'),
  ('c0108ea0-b83b-4982-b423-eb0286915757', 'midnight-library', 'The Midnight Library', null, array['Matt Haig']::text[], 'Between life and death, Nora Seed finds a library of every life she might have lived, and gets to try them on.', 'https://covers.openlibrary.org/b/isbn/9780525559474-L.jpg?default=false', '9780525559474', null, null, null, 2020, 'Viking', 288, 'English', array['contemporary','fantasy']::text[], array['hopeful','cosy']::text[], '2025-06-22T10:38:54.980Z'),
  ('fede530f-1d11-4a07-bf1f-7549f4189b12', 'intermezzo', 'Intermezzo', null, array['Sally Rooney']::text[], 'Two grieving brothers — a chess prodigy and a lawyer — stumble through love and their father''s death. Rooney''s most ambitious and most tender.', 'https://covers.openlibrary.org/b/isbn/9780374602635-L.jpg?default=false', '9780374602635', null, null, null, 2024, 'Farrar, Straus and Giroux', 448, 'English', array['contemporary','literary fiction']::text[], array['reflective','melancholic','romantic']::text[], '2025-06-22T12:27:48.980Z'),
  ('06262751-2db5-4dcf-97b9-58ead3f0e2f1', 'small-things', 'Small Things Like These', null, array['Claire Keegan']::text[], 'In an Irish town in the weeks before Christmas 1985, a coal merchant makes a discovery at the local convent. A perfect, quiet novella about complicity and courage.', 'https://covers.openlibrary.org/b/isbn/9780802158741-L.jpg?default=false', '9780802158741', null, null, null, 2021, 'Grove Press', 128, 'English', array['literary fiction','historical fiction']::text[], array['reflective','hopeful','cosy']::text[], '2025-06-22T12:34:24.980Z'),
  ('c13dac92-b829-4c31-b332-02cd0e1dfb9c', 'demon-copperhead', 'Demon Copperhead', null, array['Barbara Kingsolver']::text[], 'David Copperfield transplanted to the opioid-era mountains of southern Appalachia, told by a boy with a voice you won''t forget.', 'https://covers.openlibrary.org/b/isbn/9780063251922-L.jpg?default=false', '9780063251922', null, null, null, 2022, 'Harper', 560, 'English', array['literary fiction','contemporary']::text[], array['heartbreaking','funny']::text[], '2025-06-22T09:39:48.980Z'),
  ('1f673cdf-1a23-4068-8e67-02e58c2e99df', 'fourth-wing', 'Fourth Wing', null, array['Rebecca Yarros']::text[], 'Violet Sorrengail was meant for the quiet life of a scribe. Instead she''s ordered into a war college for dragon riders, where the dragons choose — and burn — who they like.', 'https://covers.openlibrary.org/b/isbn/9781649374042-L.jpg?default=false', '9781649374042', null, null, null, 2023, 'Entangled: Red Tower', 498, 'English', array['fantasy','romance']::text[], array['adventurous','romantic','tense']::text[], '2025-06-22T10:14:54.980Z'),
  ('e0d46716-8e06-41c1-8d2a-604796eca08b', 'bunny', 'Bunny', null, array['Mona Awad']::text[], 'A scholarship student in an elite MFA programme is invited into a clique of girls who call each other Bunny. Heathers meets a fever dream.', 'https://covers.openlibrary.org/b/isbn/9780525559726-L.jpg?default=false', '9780525559726', null, null, null, 2019, 'Viking', 307, 'English', array['horror','dark academia','contemporary']::text[], array['unsettling','funny']::text[], '2025-06-22T12:14:54.980Z'),
  ('2e3a1f36-5f5a-4768-bfcb-db564347f280', 'stoner', 'Stoner', null, array['John Williams']::text[], 'The quiet life of an assistant professor of English at the University of Missouri. Nothing happens and it is devastating.', 'https://covers.openlibrary.org/b/isbn/9781590171998-L.jpg?default=false', '9781590171998', null, null, null, 1965, 'NYRB Classics', 278, 'English', array['classics','literary fiction']::text[], array['melancholic','reflective']::text[], '2025-06-22T11:31:24.980Z'),
  ('fc5fa64a-d839-402a-9ef9-122c3704b294', 'kindred', 'Kindred', null, array['Octavia E. Butler']::text[], 'Dana, a Black writer in 1976 Los Angeles, is repeatedly pulled back in time to a Maryland plantation to save the life of a white ancestor.', 'https://covers.openlibrary.org/b/isbn/9780807083697-L.jpg?default=false', '9780807083697', null, null, null, 1979, 'Beacon Press', 264, 'English', array['sci-fi','historical fiction','classics']::text[], array['tense','unsettling']::text[], '2025-06-22T09:14:00.980Z'),
  ('597dbe38-ae35-401c-9bca-9efe5aa824a7', 'if-we-were-villains', 'If We Were Villains', null, array['M. L. Rio']::text[], 'Seven Shakespeare students at an elite conservatory begin to play their roles offstage, and one of them ends up dead.', 'https://covers.openlibrary.org/b/isbn/9781250095282-L.jpg?default=false', '9781250095282', null, null, null, 2017, 'Flatiron', 354, 'English', array['dark academia','mystery']::text[], array['tense','melancholic']::text[], '2025-06-22T09:57:48.980Z');
