insert into public.reviews (id, user_id, book_id, rating, title, body, contains_spoilers, is_reread, visibility, created_at, updated_at) values
  ('002eceb8-c751-4d2a-8a6d-54f3eb31c366', '5f54384a-ea71-406c-a187-412bf669f09a', 'cae096d0-4811-466c-b032-eb01a21da296', 5, 'a love letter to bad decisions in good coats', 'Fourth reread and I still think the first sentence is a dare. Richard is the most unreliable kind of narrator: the one who desperately wants you to like the people he''s describing. Every time I go back I catch him lying a little earlier.
insert into public.quotes (id, user_id, book_id, body, page, commentary, visibility, created_at) values
  ('233ca1c9-17cf-4169-ac3c-a87013125602', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', '9cb6880e-10ae-4805-afaa-d721fc295c3b', 'The Beauty of the House is immeasurable; its Kindness infinite.', null, 'Saying this to myself every morning now.', 'public', '2026-08-28T09:38:36.980Z'),
  ('d37f473c-2ef5-4f5f-bcde-fb7365a76205', '5f54384a-ea71-406c-a187-412bf669f09a', 'cae096d0-4811-466c-b032-eb01a21da296', 'Does such a thing as ''the fatal flaw,'' that showy dark crack running down the middle of a life, exist outside literature?', '1', 'The first line that started it all.', 'public', '2026-09-27T10:00:30.980Z'),
  ('b55c7b54-80de-496a-9b14-a5ac1e374b5d', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', '86f39409-f9ed-414f-9057-ed091d8d380d', 'I took a deep breath and listened to the old brag of my heart. I am, I am, I am.', null, 'Written on a post-it on my mirror.', 'public', '2026-10-29T09:56:54.980Z'),
  ('52ec827e-f0bd-4f99-b0bf-98bc0dea0869', 'acd968b4-7d37-4bc2-bda2-10d7e078686c', 'f613a2e3-69c0-4bd8-a4ec-fb5a8cdea4e4', 'I am no bird; and no net ensnares me: I am a free human being with an independent will.', null, null, 'public', '2026-08-12T11:05:00.980Z'),
  ('42081f47-1446-410c-bf9f-e3fa6d7b8657', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', '127e4dec-d97b-4f65-8ad7-8c6d02eedb64', 'Mrs. Dalloway said she would buy the flowers herself.', '3', 'The best opening sentence in English, don''t @ me.', 'public', '2026-11-03T12:34:24.980Z'),
  ('e9c5002a-cef4-4f05-a56d-72dc1fc373bd', '3eca6936-a445-4846-badd-47eb4e0a2f5d', '433234b6-05d9-4940-9154-393190c78cad', 'It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.', null, null, 'public', '2026-09-13T10:44:00.980Z'),
  ('c6223bbb-5ee0-4bbc-9b6f-1cabec4aed21', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', 'd6eb9eca-3445-419f-ac5a-fec9e65d350c', 'Beware; for I am fearless, and therefore powerful.', null, 'The creature had a point.', 'public', '2026-08-22T09:29:36.980Z'),
  ('4f45ac11-420b-4096-96a7-adfc76279f18', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', 'ec465430-272e-445d-ae14-e0ccb0a4dc5c', 'Last night I dreamt I went to Manderley again.', '1', null, 'public', '2026-09-18T10:08:54.980Z'),
  ('e3afae74-e2ba-4d7f-a55b-8f9abda80818', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', 'd16151ce-3f9d-4ef3-bdb1-7caee92f1231', '…and whatever walked there, walked alone.', '1', 'Chills, every single time.', 'public', '2026-10-20T12:53:00.980Z'),
  ('596eb223-d64c-4b9b-a7b5-8945a1ca1bf7', 'acd968b4-7d37-4bc2-bda2-10d7e078686c', 'e6bd3ded-838c-4711-89e0-be78f7736474', 'Whatever our souls are made of, his and mine are the same.', null, null, 'public', '2026-10-31T12:39:48.980Z'),
  ('89d7b2e1-d1de-4651-bbb5-5aa87c5bf4eb', '3eca6936-a445-4846-badd-47eb4e0a2f5d', 'f6d6ee67-a698-435c-bf45-c86e7bfe29ac', 'He is half of my soul, as the poets say.', null, 'I''m fine. Totally fine.', 'public', '2026-09-29T10:56:18.980Z'),
  ('8ab5b379-bbc3-46a2-8837-9f7eeec28782', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', 'e66bf754-65ea-4692-9c11-8dc2f964f081', 'But in a solitary life, there are rare moments when another soul dips near yours, as stars once a year brush the earth.', null, null, 'public', '2026-10-11T11:13:42.980Z'),
  ('d592e543-b491-4aa5-b2ca-0f2447df8712', '1841d756-5b33-4b76-9f55-d4e86d91f5e0', '319cd7bf-5890-48e7-80fc-d4ecf9f47f59', 'I must not fear. Fear is the mind-killer.', null, 'Reading this before every dentist appointment.', 'public', '2026-11-02T10:08:18.980Z'),
  ('bdeef026-17b5-4f00-8fa9-0d77e74e98c4', '1841d756-5b33-4b76-9f55-d4e86d91f5e0', '955cae93-d2f5-436b-b898-3d1eea828957', 'And once the storm is over, you won''t remember how you made it through, how you managed to survive.', null, null, 'public', '2026-10-09T11:32:18.980Z'),
  ('b74a1998-acc6-46fc-a592-794388f7c7b0', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', '45f06cf9-4d8d-482a-b0d7-ba7d47695289', 'Suppose I were to begin by saying that I had fallen in love with a color.', '1', null, 'public', '2026-10-14T11:55:42.980Z'),
  ('65ca03db-b8b1-4bca-9499-429473c4dab8', 'f290e8d0-65e6-45be-8b0c-4f7feeee92a1', '14576130-d4e9-4b8c-9963-096e0d8ab9e1', 'The only way to get rid of a temptation is to yield to it.', null, 'Wilde was a menace and I love him.', 'public', '2026-09-07T13:10:42.980Z'),
  ('b88e87f3-1a43-49f6-8425-b5f023948205', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', '1abf9a57-8de1-4a41-9977-c473ddd36c7f', 'Let me begin again.', '3', null, 'public', '2026-10-04T12:46:42.980Z'),
  ('99252e48-0f80-4bcd-ad90-d4ed68d16fba', 'acd968b4-7d37-4bc2-bda2-10d7e078686c', '6dea3f39-b22e-4346-81e9-3dfc3df54cd4', 'The circus arrives without warning.', '3', null, 'public', '2026-10-05T12:39:12.980Z'),
  ('abe898f0-7bb5-4176-91c2-770b4fa06f4d', '61772e2e-fe1a-4c4e-a610-af2629180030', 'c0108ea0-b83b-4982-b423-eb0286915757', 'Between life and death there is a library.', null, null, 'public', '2026-10-26T09:15:30.980Z'),
  ('fb21cb8b-8c0a-41c2-ba08-b3007d9e61f2', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', '1baa8c28-6fa6-477d-a408-8be7d491e73c', 'Because survival is insufficient.', null, null, 'public', '2026-07-27T13:53:54.980Z');
insert into public.lists (id, user_id, title, description, cover_style, cover_image_url, visibility, is_ranked, created_at, updated_at) values
  ('a164be56-c5da-4cf1-aed1-b5715a10a878', '1841d756-5b33-4b76-9f55-d4e86d91f5e0', 'Books that feel like Radiohead songs', 'Paranoid androids, quiet dread, weirdly tender. Best read with headphones on and the lights low.', 'ink', null, 'public', false, '2026-10-23T11:36:12.980Z', '2026-10-23T11:36:12.980Z'),
  ('a69041c6-7ebf-4420-908b-aa5b4daeaaa0', '3eca6936-a445-4846-badd-47eb4e0a2f5d', 'Books that broke my heart', 'Ranked by how long I had to stare at the ceiling afterwards.', 'rose', null, 'public', true, '2026-10-15T10:49:24.980Z', '2026-10-15T10:49:24.980Z'),
  ('94dfffc7-67f9-4fe7-a9ab-33cbbcf60084', 'f290e8d0-65e6-45be-8b0c-4f7feeee92a1', 'Literature for overthinkers', 'Narrators who think about thinking. If you''ve ever replayed a conversation from 2017 at 3am, welcome home.', 'sage', null, 'public', false, '2026-10-27T11:34:42.980Z', '2026-10-27T11:34:42.980Z'),
  ('2bc219b8-af70-48b3-9ea3-3ed52fb60ec0', 'acd968b4-7d37-4bc2-bda2-10d7e078686c', 'Books to read on a rainy Sunday', 'Kettle on. Socks on. Phone in another room.', 'butter', null, 'public', false, '2026-10-30T12:16:06.980Z', '2026-10-30T12:16:06.980Z'),
  ('7fd049ac-90a2-4e4a-bce0-a31427517ef2', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', 'My literary red flags', 'Men I would have married anyway. A cautionary tale in six volumes.', 'burgundy', null, 'public', false, '2026-10-19T09:54:12.980Z', '2026-10-19T09:54:12.980Z'),
  ('0b72d408-4604-4a1f-9369-5b64e25bcf42', '5f54384a-ea71-406c-a187-412bf669f09a', 'Dark academia, a starter kit', 'Tweed, Greek, terrible choices. Read in this order for maximum unease.', 'collage', null, 'public', true, '2026-09-30T13:47:54.980Z', '2026-09-30T13:47:54.980Z'),
  ('3093e118-6565-44ef-9195-c99a1ef79531', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', 'Myths, retold by the people they happened to', 'Gods, witches and boys who loved heroes, finally getting the mic.', 'sage', null, 'public', false, '2026-10-08T12:47:54.980Z', '2026-10-08T12:47:54.980Z'),
  ('0f5057d4-027a-4e55-aca3-1506e5fc2746', '5f54384a-ea71-406c-a187-412bf669f09a', 'Gifts for my sister (shh)', 'Don''t look, Isla.', 'butter', null, 'private', false, '2026-11-01T09:44:54.980Z', '2026-11-01T09:44:54.980Z');
