  ('46b05fe3-8675-4b25-a313-134780c54e2a', 'a5d2cc7c-ad31-436d-9c7e-f0ae2eb299cc', null, null, null, null, 'Page 212 and the footnotes have started fighting each other. Love it here.', null, 39, 'public', '5f54384a-ea71-406c-a187-412bf669f09a', 'update', '2026-11-04T07:38:00.980Z'),
  ('e34b6e79-a32a-401a-91e7-a6f0050f922b', '2e3a1f36-5f5a-4768-bfcb-db564347f280', null, null, null, null, 'Reading Stoner on a delayed train feels thematically appropriate.', null, 50, 'public', 'f290e8d0-65e6-45be-8b0c-4f7feeee92a1', 'update', '2026-11-03T19:47:00.980Z'),
  ('15b0b264-227b-47ea-baf0-fd958dc01384', '319cd7bf-5890-48e7-80fc-d4ecf9f47f59', null, null, null, null, 'Page 301. The spice must flow and so must my coffee.', null, 49, 'public', '1841d756-5b33-4b76-9f55-d4e86d91f5e0', 'update', '2026-11-03T13:48:12.980Z'),
  ('eb1d32cf-450d-4e3c-a338-25d5c9cd78c2', '6dea3f39-b22e-4346-81e9-3dfc3df54cd4', null, null, null, null, 'Le Cirque des Rêves has entered my dreams, literally. Halfway and swooning.', null, 40, 'public', '3eca6936-a445-4846-badd-47eb4e0a2f5d', 'update', '2026-11-03T04:25:24.980Z'),
  ('74abf871-06af-4d14-b365-582b0607c7a8', '127e4dec-d97b-4f65-8ad7-8c6d02eedb64', null, null, null, null, 'Reading Woolf on a park bench like the cliché I aspire to be.', null, 45, 'public', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', 'update', '2026-11-02T15:05:36.980Z'),
  ('ef32cae7-0d4c-441a-96d3-48d8ccb84491', '8a083731-5d62-4ade-b584-42be651378f1', null, null, null, null, 'June Hayward is the worst person I''ve ever spent a weekend with and I cannot stop.', null, 28, 'public', '61772e2e-fe1a-4c4e-a610-af2629180030', 'update', '2026-11-03T23:36:12.980Z'),
  ('2d793eff-e2f0-4fbf-868c-932b29e9f2dc', 'c13dac92-b829-4c31-b332-02cd0e1dfb9c', null, null, null, null, 'Demon''s voice is so alive. Dickens would be proud and also a bit jealous.', null, 43, 'public', '11f2e717-7b9b-4abd-a567-6a7de501fdab', 'update', '2026-11-03T10:29:36.980Z'),
  ('beb8e3ea-f920-4f26-9e18-8a57d6c64afd', '50ba1b5f-cc09-4dba-af91-d844b236c3e9', null, null, null, null, 'If you loved Piranesi''s quiet strangeness, try Le Guin''s ice planet next. Same feeling of being let into a world slowly.', null, null, 'public', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', 'recommendation', '2026-11-02T05:23:00.980Z'),
  ('c4e5aa5e-e9cc-4f67-9996-ace531a8f1e3', 'd16151ce-3f9d-4ef3-bdb1-7caee92f1231', null, null, null, null, 'October is over but Hill House season never ends. 182 pages. No excuses.', null, null, 'public', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', 'recommendation', '2026-10-31T22:08:54.980Z'),
  ('5f2e5d4a-74ac-4bbf-85a5-a9f3ca805563', null, null, null, null, 'fe2aba6c-82d7-4430-bd0a-8fdd7e364def', null, null, null, 'public', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', 'repost', '2026-11-04T05:21:12.980Z');
