  ('2070cbe5-01ae-4de7-bf0e-4a2003495864', '82591b36-9e78-4295-9b2f-da33c4a518b8', '5ec8a2e5-0d9d-40e9-81d0-61e5e3e0de4d', null, 'Henry and his reading glasses. You''ve ruined me.', '2026-09-27T05:56:18.980Z'),
  ('8d12523c-88dd-4c37-87c7-c1ddf04a8a05', '82591b36-9e78-4295-9b2f-da33c4a518b8', 'f290e8d0-65e6-45be-8b0c-4f7feeee92a1', null, 'Fourth reread?? Respect. I''m scared to do a second.', '2026-09-27T09:56:18.980Z'),
  ('2a71ecd0-3ddd-4607-88a5-0dc343955f3b', '67f7c309-322f-42a9-8973-a6c4c0f5b893', '3eca6936-a445-4846-badd-47eb4e0a2f5d', null, '"I want to plant a garden about it" is the most accurate review of Circe ever written.', '2026-10-11T11:16:42.980Z'),
  ('84fa7828-6985-41cf-b0b9-9e49112c13c2', '1f0dabb3-9a16-4b3a-9e44-1950f495d03d', '2a95913c-34a2-4cb1-823f-8bc5822b24d5', null, 'Peter''s chapters!!! I had to read them out loud to keep up.', '2026-11-02T02:24:30.980Z'),
  ('c3d8262d-b42f-415e-bc0f-dc067141d835', '31e94e3f-130c-4a3b-9b8c-a554c644331f', '1841d756-5b33-4b76-9f55-d4e86d91f5e0', null, 'Should I add Piranesi as ''Everything in Its Right Place''?', '2026-10-24T16:36:12.980Z'),
  ('cecda0f5-1202-42b4-88b1-63e7a8d27835', '31e94e3f-130c-4a3b-9b8c-a554c644331f', 'b105dbf5-10b2-43ef-b593-6a0b9a73d99d', null, 'Yes, and Le Guin is ''Reckoner''.', '2026-10-24T11:36:12.980Z'),
  ('7a73bbbf-31f9-427a-8537-0bc338cc301a', 'fa84040c-ff54-4a73-a82f-902c260f54cc', 'acd968b4-7d37-4bc2-bda2-10d7e078686c', null, 'Die on this hill (house). Iconic.', '2026-10-21T06:42:48.980Z'),
  ('e3daff82-0ac9-4668-b302-cab0500b0e4f', '98cdbef5-78bb-44ef-b651-486c5b0c5570', '61772e2e-fe1a-4c4e-a610-af2629180030', null, 'Okay fine I''m adding it to my TBR.', '2026-10-22T11:27:30.980Z'),
  ('11586d4a-e2e4-444a-88e5-a5d5609bf8cf', '70ec765e-6a08-4ad1-a956-222430ae4cb8', '5f54384a-ea71-406c-a187-412bf669f09a', null, 'Henry being on this list is personal and correct.', '2026-10-20T13:54:12.980Z'),
  ('55c76e38-296d-4dae-9e2b-f66984e51151', 'ec56fe26-1b6d-488d-a798-ec8912d689d5', '11f2e717-7b9b-4abd-a567-6a7de501fdab', null, 'I have this one written inside my journal cover.', '2026-10-29T16:56:54.980Z'),
  ('e830b061-60dc-4073-9eb1-5c25720c417d', '82591b36-9e78-4295-9b2f-da33c4a518b8', '5f54384a-ea71-406c-a187-412bf669f09a', '2070cbe5-01ae-4de7-bf0e-4a2003495864', 'He''d read Homer at your funeral and you''d thank him for it.', '2026-09-27T07:56:18.980Z'),
